    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers
    // Original arrays:
    //   C[n][n], A[n][m], B[n][m]
    // Our mapping:
    //   C[i][j]   -> C(j, i)    with shape (n, n)
    //   A[i][j]   -> A(j, i)    with shape (m, n)
    //   B[i][j]   -> B(j, i)    with shape (m, n)
    Buffer<num_t, 2> C(n, n);
    Buffer<num_t, 2> A(m, n);
    Buffer<num_t, 2> B(m, n);

