    // We compute for all (i,j) in [0..n-1]×[0..n-1], but apply the update
    // only when j <= i. For j > i, C[i][j] remains as initialized.
    //
    // Mapping of array accesses:
    //   C[i][j]   -> C_param(j, i)
    //   A[j][k]   -> A_param(k, j)
    //   B[i][k]   -> B_param(k, i)
    //   B[j][k]   -> B_param(k, j)
    //   A[i][k]   -> A_param(k, i)

    Func syr2k("syr2k");

    // Scalar parameters as Halide Exprs
    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Initial multiplication by beta for j <= i; otherwise keep original C.
    // This matches:
    //   if (j <= i) C[i][j] *= beta; else C[i][j] unchanged.
    syr2k(j, i) = select(j <= i,
                         beta_e * C_param(j, i),
                         C_param(j, i));

    // Rank-2k update, only for j <= i:
    //   C[i][j] += alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k])
    syr2k(j, i) += select(
        j <= i,
        alpha_e * (A_param(k, j) * B_param(k, i) +
                   B_param(k, j) * A_param(k, i)),
        cast<num_t>(0));

    // -------------------------
    // Optimized schedule
    // -------------------------
    //
    // Goals:
    //  * Exploit parallelism across rows i (independent outputs).
    //  * Vectorize along j (contiguous in memory for C).
    //  * Preserve good data locality for C and reasonable access
    //    patterns for A and B.
    //  * Keep semantics identical (including only updating j <= i).
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

