    syr2k
        .compute_root()
        // Make j the innermost loop (row-major over C: C(j, i))
        .reorder(j, i)
        // Parallelize across rows i (outer dimension).
        .parallel(i)
        // Vectorize across contiguous j.
        .vectorize(j, vec_width)
        // Explicit bounds (not strictly necessary, but helps the compiler).
        .bound(j, 0, n)
        .bound(i, 0, n);

