    //  * Keep j innermost (for vectorization, contiguous C access).
    //  * Iterate over k just outside j, so for each (i,k) we sweep
    //    over a whole row j vectorized.
    syr2k.update()
        .reorder(j, k, i)      // innermost -> outermost: j, k, i
        .parallel(i)
        .vectorize(j, vec_width);

    // JIT-compile the kernel for the chosen target.
    syr2k.compile_jit(target);

    // Time the execution (boilerplate kept intact)
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C (in-place update relative to C_param)
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
