    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tunable tile sizes. 64x32 works well on many x86-64 CPUs.
    const int tile_j = 64;  // along j (x, contiguous)
    const int tile_i = 32;  // along i (y)

    Var jo("jo"), io("io"), jj("jj"), ii("ii");

    // Pure definition:
    //
    // Loops (conceptually):
    //   for (io tiles of i, parallel)
    //     for (jo tiles of j)
    //       for (ii inside tile_i)
    //         for (jj inside tile_j, vectorized)
    //
    syr2k
        .tile(j, i,  // original vars: x=j (fast), y=i
              jo, io, jj, ii,
              tile_j, tile_i)
        .vectorize(jj, vec_width)
        .parallel(io);

    // Update (reduction over k):
    //
    // We apply the same tiling on (i,j), then iterate k inside each tile.
    // Loop order after reorder(jj, ii, k, jo, io):
    //
    //   for (io tiles of i, parallel)
    //     for (jo tiles of j)
    //       for (k in [0..m-1])
    //         for (ii inside tile_i)
    //           for (jj inside tile_j, vectorized)
    //
    // This keeps the active C tile in cache while streaming over k.
    syr2k.update()
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        .reorder(jj, ii, k, jo, io)
        .vectorize(jj, vec_width)
        .parallel(io);

    // JIT-compile the kernel for the host target
    syr2k.compile_jit(target);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Recall: C(ii,jj) in C maps to C(jj,ii) in Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
