        Expr b_ik = B_param(k, i);

        Expr contrib = a_jk * b_ik + b_jk * a_ik;

        // Only accumulate on the lower triangle; for j > i we add zero.
        Expr zero = cast(type_of<num_t>(), 0);
        syr2k(j, i) += alpha_e * select(j <= i, contrib, zero);
